"""Dead code elimination optimization pass."""

from typing import List, Set
from basic_block import BasicBlock
from opcodes import Instruction


class DeadCodeEliminationPass:
    @staticmethod
    def optimize_block(block: BasicBlock) -> List[Instruction]:
        # Collect variables read by instructions
        used_vars: Set[str] = set()
        for instr in reversed(block.instructions):
            if instr.op == "RETURN" and instr.arg:
                used_vars.add(str(instr.arg))
            elif instr.op == "ADD" and isinstance(instr.arg, tuple):
                used_vars.add(str(instr.arg[0]))
                used_vars.add(str(instr.arg[1]))

        # Backward dead store elimination
        surviving: List[Instruction] = []
        for instr in reversed(block.instructions):
            # BUG: Strips CALL / side-effect instructions if target_var is not in used_vars!
            # Fails to treat instr.has_side_effect or op in ("CALL", "RETURN") as unconditional roots!
            if instr.target_var and instr.target_var not in used_vars and not instr.has_side_effect:
                continue  # Dead store removed
            elif instr.op == "CALL" and instr.target_var and instr.target_var not in used_vars:
                continue  # BUG: Erroneously prunes external function calls!

            surviving.append(instr)
            if instr.target_var and instr.target_var in used_vars:
                used_vars.discard(instr.target_var)
            if instr.op in ("LOAD", "CONST") and instr.arg:
                used_vars.add(str(instr.arg))
        return list(reversed(surviving))

