"""JIT compiler optimization pipeline."""

from basic_block import BasicBlock
from dce_pass import DeadCodeEliminationPass
from opcodes import Instruction


class JITOptimizer:
    def __init__(self):
        self.dce = DeadCodeEliminationPass()

    def run(self, block: BasicBlock) -> None:
